ttonSendMood constraints... buttonSendMood.centerXAnchor.constraint(equalTo: view.safeAreaLayoutGuide.centerXAnchor), buttonSendMood.topAnchor.constraint(equalTo: moodPicker.bottomAnchor, constant: 16), ]) } } {% endcode %}
