ldEmail.topAnchor.constraint(equalTo: textFieldName.bottomAnchor, constant: 16), textFieldEmail.centerXAnchor.constraint(equalTo: self.safeAreaLayoutGuide.centerXAnchor), textFieldEmail.widthAnchor.constraint(equalTo: self.safeAreaLayoutGuide.widthAnchor, multiplier: 0.9), textFieldPassword.topAnchor.constraint(equalTo: textFieldEmail.bottomAnchor, constant: 16), textFieldPassword.centerXAnchor.constraint(equalTo: self.safeAreaLayoutGuide.centerXAnchor), textFieldPassword.widthAnchor.constraint(equalTo: self.safeAreaLayoutGuide.widthAnchor, multiplier: 0.9), buttonRegister.topAnchor.constraint(equalTo: textFieldPassword.bottomAnchor, constant: 32), buttonRegister.centerXAnchor.constraint(equalTo: self.safeAreaLayoutGuide.centerXAnchor), ]) } required init?(coder: NSCoder) { fatalError(&#34;init(coder:) has not been implemented&#34;) } }The above code is very straightforward to display three text fields: name, email, password, and a register button.
