Making the API call for the endpoint &lsquo;add.&rsquo;# We need to use Alamofire to POST the new contact we created above to the server. We now write the following code in addANewContact(contact: Contact) method:
{% code lineNumbers=&ldquo;true&rdquo; %}
//MARK: add a new contact call: add endpoint... func addANewContact(contact: Contact){ if let url = URL(string: APIConfigs.baseURL+&#34;add&#34;){ AF.request(url, method:.post, parameters: [ &#34;name&#34;: contact.name, &#34;email&#34;: contact.email, &#34;phone&#34;: contact.phone ]) .responseString(completionHandler: { response in //MARK: retrieving the status code... let status = response.response?.statusCode switch response.result{ case .success(let data): //MARK: there was no network error... //MARK: status code is Optional, so unwrapping it... if let uwStatusCode = status{ switch uwStatusCode{ case 200...299: //MARK: the request was valid 200-level... self.getAllContacts() self.clearAddViewFields() break case 400...499: //MARK: the request was not valid 400-level... print(data) break default: //MARK: probably a 500-level error... print(data) break } } break case .failure(let error): //MARK: there was a network error... print(error) break } }) }else{ //alert that the URL is invalid... } }{% endcode %}
In the above code:
